// MovieTicket.javaclass MovieTicket {    // Attributes    String movieName;    int seatNumber;    double price;    boolean isBooked;    // Constructor    MovieTicket() {        this.isBooked = false; // Ticket initially not booked    }    // Method to book a ticket    void bookTicket(String movieName, int seatNumber, double price) {        if (!isBooked) {            this.movieName = movieName;            this.seatNumber = seatNumber;            this.price = price;            this.isBooked = true;            System.out.println("Ticket booked successfully!");        } else {            System.out.println("Ticket already booked.");        }    }    // Method to display ticket details    void displayTicketDetails() {        if (isBooked) {            System.out.println("Movie Ticket Details:");            System.out.println("Movie Name: " + movieName);            System.out.println("Seat Number: " + seatNumber);            System.out.println("Price: $" + price);        } else {            System.out.println("No ticket booked yet.");        }    }}// Main class to test MovieTicket classpublic class MovieTicketSystem {    public static void main(String[] args) {        // Create a MovieTicket object        MovieTicket ticket = new MovieTicket();        // Try to display ticket details before booking        ticket.displayTicketDetails();        // Book the ticket        ticket.bookTicket("Avengers: Endgame", 15, 12.50);        // Display ticket details after booking        ticket.displayTicketDetails();        // Try booking again to test the condition        ticket.bookTicket("Another Movie", 20, 15.00);    }}